\begin{figure}
    \centering
    <<IMG_421>>
    \captionsetup{skip=0pt}  
    \caption{\textbf{Визуализация сгенерированных результатов.} {\agent} создаёт презентационные видео с богатым, детализированным содержанием слайдов, точным позиционированием курсора и вовлекающим докладчиком; в отличие от него, Veo3~<<CMD_547>> даёт размытый текст и неполное покрытие информации, а PresentAgent~<<CMD_548>> создаёт слайды, перегруженные текстом, и страдает от проблем с переполненной версткой и неточной информацией (\textit{например,} название и учреждения).}
    <<CMD_579>>
    \vspace{-0.2\baselineskip} 
\end{figure}
<<COMMENT_327>>
\vspace{-0.5\baselineskip}

